service.method:

UPDATE SMAND SET
	RECE_COMPANY_CODE = ${RECE_COMPANY_CODE}
	,RECE_USER_ID	  = ${RECE_USER_ID}
	,START_DATE       = ${START_DATE}
	,END_DATE         = ${END_DATE}
	,DESCRIPTION      = ${DESCRIPTION}
	,CHANGE_DATE      = ${current.date}
	,CHANGE_TIME      = ${current.time}
	,CHANGE_USER_ID   = ${session.ID}
WHERE  1=1
	AND DELEGATION_KEY 	 = ${DELEGATION_KEY}


DELETE FROM SMAND
WHERE 1 = 1
	AND HOUSE_CODE       = ${HOUSE_CODE}
	AND COMPANY_CODE     = ${COMPANY_CODE}
	AND MAND_TYPE        = ${MAND_TYPE}
	AND GIVE_COMPANY_CODE= ${GIVE_COMPANY_CODE}
	AND GIVE_USER_ID     = ${GIVE_USER_ID}
	AND RECE_COMPANY_CODE= ${RECE_COMPANY_CODE}
	AND RECE_USER_ID     = ${RECE_USER_ID}
	AND DELEGATION_KEY	 = ${DELEGATION_KEY}


SELECT GIVE_USER_ID
	  ,RECE_USER_ID
FROM SMAND
WHERE 
	HOUSE_CODE       = ${session.HOUSE_CODE}
AND COMPANY_CODE     = ${session.COMPANY_CODE}
AND MAND_TYPE		 = '01'
AND RECE_USER_ID	 = ${session.ID}
AND GIVE_USER_ID	 = ${APP_USER_ID}
AND ${current.date} BETWEEN START_DATE AND END_DATE


UPDATE SAPPP 
   SET POSTPROCESSED = ${POSTPROCESSED}
 WHERE HOUSE_CODE = ${HOUSE_CODE} 
   AND COMPANY_CODE = ${COMPANY_CODE} 
   AND SMR_NUMBER = ${SMR_NUMBER} 
   AND SEQ = ${PP_SEQ}


UPDATE SSIAD 
   SET SMR_STATUS = ${SMR_STATUS}
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
 WHERE HOUSE_CODE = ${HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND SMR_NUMBER = ${SMR_NUMBER}


UPDATE SSETL 
   SET SMR_STATUS = ${SMR_STATUS}
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
 WHERE HOUSE_CODE = ${HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND SMR_NUMBER = ${SMR_NUMBER}
